export function weaponCategorySupportsAmmo(category: WeaponCategory): boolean {
  return category === 'unarmed'
    || category === 'meleeWeapons'
    || category === 'smallGuns'
    || category === 'bigGuns'
    || category === 'energyWeapons'
    || category === 'minesTraps';
}

