export function getWeaponById(id: string): Weapon | undefined {
  return BUILT_IN_WEAPONS.find(w => w.id === id);
}

/**
 * Return the shared area-effect profile for a weapon, when one exists.
 *
 * The reference is optional so old persisted/custom Weapon objects remain
 * valid.  A fresh object is returned to keep callers from mutating the
 * canonical catalog entry while pre-filling a modal's rolled damage.
 */
export function getWeaponAreaAttack(weapon: Weapon): AreaAttack | undefined {
  const profileId = weapon.areaAttackProfileId;
  const profile = profileId ? MINE_TRAP_PROFILES[profileId] : undefined;
  return profile ? { ...profile } : undefined;
}

/**
 * Hands required to wield a weapon (1 or 2).
 * Uses the weapon's explicit `hands` when set (all built-ins are tagged).
 * Custom weapons fall back: two-handed if minStr >= 6 or category is bigGuns,
 * otherwise inferred one-handed (natural/unarmed always one-handed).
 */
export function getWeaponHands(w: Weapon): 1 | 2 {
  if (w.hands === 1 || w.hands === 2) return w.hands;
  if (w.category === 'natural' || w.category === 'unarmed') return 1;
  if (w.category === 'bigGuns') return 2;
  if (w.minStr >= 6) return 2;
  return 1;
}

export function isMeleeWeapon(w: Weapon): boolean {
  if (w.attackDelivery) return w.attackDelivery === 'melee';
  return w.category === 'meleeWeapons' || w.category === 'unarmed' || w.category === 'natural';
}

export function isRangedWeapon(w: Weapon): boolean {
  if (w.attackDelivery) return w.attackDelivery === 'ranged';
  return !isMeleeWeapon(w) && w.category !== 'throwing';
}

/** Melee/unarmed/natural weapons add the wielder's melee damage bonus. */
export function addsMeleeDamage(w: Weapon): boolean {
  return isMeleeWeapon(w);
}

export function formatWeaponDamage(w: Weapon): string {
  const base = `${w.damageDieCount}d${w.damageDie}`;
  const bonus = w.damageBonus !== 0 ? (w.damageBonus > 0 ? `+${w.damageBonus}` : `${w.damageBonus}`) : '';
  const type = `(${w.damageType === 'normal' ? 'N' : w.damageType === 'laser' ? 'L' : w.damageType === 'fire' ? 'F' : w.damageType === 'plasma' ? 'P' : 'E'})`;
  return `${base}${bonus} ${type}`;
}

/** Format the manual's AP S/T/B costs, falling back to standard costs. */
export function formatWeaponAP(w: Weapon): string {
  const s = w.apSingle ?? 4;
  const t = w.apTargeted === null ? '—' : (w.apTargeted ?? 5);
  const b = w.apBurst === null ? '—' : (w.apBurst ?? 6);
  return `Single ${s} / Target ${t} / Burst ${b}`;
}

/** Show capacity only for weapons with a positive ammo capacity. */
export function formatWeaponCapacity(w: Pick<Weapon, 'magazineSize'>): string | null {
  if (!Number.isFinite(w.magazineSize) || w.magazineSize <= 0) return null;
  return `Holds ${w.magazineSize} ${w.magazineSize === 1 ? 'Round' : 'Rounds'}`;
}

export function computeModBonuses(modIds: string[]): { toHit: number; damage: number; range: number } {
  let toHit = 0, damage = 0, range = 0;
  for (const id of modIds) {
    const mod = WEAPON_MODS.find(m => m.id === id);
    if (mod) { toHit += mod.toHitBonus; damage += mod.damageBonus; range += mod.rangeBonus; }
  }
  return { toHit, damage, range };
}
